+            maxDocUsages == that.maxDocUsages &&
+            totalDocUsages == that.totalDocUsages;
+    }
+
+    @Override
+    public int hashCode() {
+        return Objects.hash(maxLines, totalLines, maxChars, totalChars, maxSourceUsages, totalSourceUsages, maxDocUsages, totalDocUsages);
+    }
+}
