+        assertEquals("indexed,omitNorms,indexOptions=DOCS<field:[76 61 6c 75 65 32]>", fields[2].toString());
+        assertEquals("docValuesType=SORTED_SET<field:[76 61 6c 75 65 32]>", fields[3].toString());
+    }
